 const [terms,setTerms]=useState<Row[]>([]),[courses,setCourses]=useState<Row[]>([]),[departments,setDepartments]=useState<Row[]>([]),[students,setStudents]=useState<Row[]>([]),[enrol,setEnrol]=useState<Row[]>([]),[grades,setGrades]=useState<Row[]>([]),[syllabi,setSyllabi]=useState<Row[]>([]),[instructors,setInstructors]=useState<Row[]>([]),[teachingAssignments,setTeachingAssignments]=useState<Row[]>([]),[timetableEntries,setTimetableEntries]=useState<Row[]>([]),[timetableEvents,setTimetableEvents]=useState<Row[]>([]);
 const [tab,setTab]=useState("overview"),[selectedTerm,setSelectedTerm]=useState(""),[search,setSearch]=useState(""),[courseDepartmentFilter,setCourseDepartmentFilter]=useState(""),[courseKindFilter,setCourseKindFilter]=useState(""),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState(""),[modal,setModal]=useState(""),[canManage,setCanManage]=useState(false),[editingEntityId,setEditingEntityId]=useState(""),[editingSyllabusId,setEditingSyllabusId]=useState(""),[printingSyllabus,setPrintingSyllabus]=useState<Row|null>(null),[instructorForm,setInstructorForm]=useState<any>({full_name:"",department_id:"",title:"",email:"",phone:"",employment_type:"full_time",notes:"",is_active:true}),[assignmentForm,setAssignmentForm]=useState<any>({term_id:"",course_id:"",instructor_id:"",weekly_hours:"3",assignment_role:"primary",notes:""}),[editingAssignmentId,setEditingAssignmentId]=useState("");
