 const save=async(table:string,payload:any)=>{if(!db||!mutationsEnabled){setNotice((englishUI?"Academic data changes are available only after the development database is separated and the feature enabled.":"학사 데이터 변경은 개발 DB 분리 및 기능 활성화 후 사용할 수 있습니다."));return;}setSaving(true);setError("");try{let insertPayload=payload;if(!editingEntityId&&["academic_terms","academic_courses","academic_instructors"].includes(table)){const {data:{user},error:userError}=await db.auth.getUser();if(userError)throw userError;if(!user)throw new Error("로그인이 필요합니다.");insertPayload={...payload,created_by:user.id};}const q=editingEntityId?db.from(table).update(payload).eq("id",editingEntityId):db.from(table).insert(insertPayload);const {data:verified,error}=await q.select("id").maybeSingle();if(error)throw error;if(!verified?.id||(editingEntityId&&verified.id!==editingEntityId))throw new Error("저장 결과를 확인할 수 없습니다.");setModal("");setNotice(editingEntityId?"정보를 수정했습니다.":"저장했습니다.");setEditingEntityId("");await load();}catch(e:any){setError(e.message||"저장에 실패했습니다.");}finally{setSaving(false);}}; const removeEntity=async(table:string,id:string)=>{if(!db||!mutationsEnabled){setNotice((englishUI?"Academic data changes are available only after the development database is separated and the feature enabled.":"학사 데이터 변경은 개발 DB 분리 및 기능 활성화 후 사용할 수 있습니다."));return;}if(!window.confirm(locale==="my"?"ဤအချက်အလက်ကို ဖျက်မလား။ ဆက်စပ်မှတ်တမ်းရှိပါက ဖျက်၍မရနိုင်ပါ။":(window.location.pathname.startsWith("/en/")?"Delete this item? Deletion is blocked if linked enrollment, grade or timetable records exist.":"이 항목을 삭제할까요? 연결된 수강·성적·시간표 기록이 있으면 삭제가 차단됩니다.")))return;setSaving(true);setError("");try{const {data:deleted,error}=await db.from(table).delete().eq("id",id).select("id").maybeSingle();if(error)throw error;if(!deleted?.id||deleted.id!==id)throw new Error("삭제 결과를 확인할 수 없습니다.");setNotice((englishUI?"Item deleted.":"항목을 삭제했습니다."));await load();}catch(e:any){setError("연결된 학사 기록이 있거나 권한이 없어 삭제할 수 없습니다. "+(e.message||""));}finally{setSaving(false);}};
 const termName=(id:string)=>terms.find(x=>x.id===id)?.name||"—",courseName=(id:string)=>{const c=courses.find(x=>x.id===id);return (locale==="my"?(c?.title_my||c?.title):c?.title)||"—";},studentName=(id:string)=>students.find(x=>x.id===id)?.full_name||"—",departmentName=(id:string)=>{const d=departments.find(x=>x.id===id);return locale==="en"?(d?.name_en||d?.name_ko||d?.name_my||""):(d?.name_ko||d?.name_en||d?.name_my||"");};
 const displayDept=(id:string)=>{const d=departments.find(x=>x.id===id);return locale==="en"?(d?.name_en||d?.name_ko||d?.name_my||""):locale==="my"?(d?.name_my||d?.name_en||d?.name_ko||""):(d?.name_ko||d?.name_en||d?.name_my||"");};
 const displayCourse=(c:Row)=>locale==="my"?(c.title_my||c.title):c.title;
 const filtered=(rows:Row[],keys:string[])=>rows.filter(x=>!search||keys.some(k=>String(x[k]||"").toLowerCase().includes(search.toLowerCase())));
 const visibleCourses=filtered(courses,["course_code","title","title_my","department"]).filter(x=>(!courseDepartmentFilter||x.department_id===courseDepartmentFilter)&&(!courseKindFilter||(x.course_kind||"major")===courseKindFilter));
