 const open=(kind:string)=>{setEditingEntityId("");setError("");if(kind==="term")setTerm({...blankTerm});if(kind==="course")setCourse({...blankCourse});if(kind==="grade")setGrade({student_id:"",course_id:"",term_id:selectedTerm,score:"",grade:"",remarks:""});setModal(kind);};
 const shareSyllabus=async(x:Row)=>{const lines=[`${englishUI?"[MRPST Syllabus]":locale==="my"?"[MRPST သင်ကြားရေးအစီအစဉ်]":"[MRPST 강의계획서]"}`,`${englishUI?"Course:":locale==="my"?"ဘာသာရပ်:":"과목:"} ${courseName(x.course_id)}`,`${englishUI?"Semester:":locale==="my"?"စာသင်ကာလ:":"학기:"} ${termName(x.term_id)}`,x.instructor?`${englishUI?"Instructor:":locale==="my"?"တာဝန်ခံသင်ကြားသူ:":"담당 교수:"} ${x.instructor}`:"",x.objectives?`${englishUI?"Course objectives:":locale==="my"?"သင်ကြားမှုရည်ရွယ်ချက်:":"강의 목표:"} ${x.objectives}`:"",x.learning_outcomes?`${englishUI?"Learning outcomes:":locale==="my"?"သင်ယူမှုရလဒ်:":"학습 성과:"} ${x.learning_outcomes}`:"",x.teaching_methods?`${englishUI?"Teaching and learning methods:":locale==="my"?"သင်ကြားသင်ယူမှုနည်းလမ်း:":"교수·학습 방법:"} ${x.teaching_methods}`:"",x.textbooks?`${englishUI?"Textbooks and references:":locale==="my"?"သင်ရိုးစာအုပ်နှင့် ကိုးကားစာအုပ်များ:":"교재 및 참고도서:"} ${x.textbooks}`:"",x.assessment_methods?`${englishUI?"Assessment methods:":locale==="my"?"အကဲဖြတ်နည်းလမ်း:":"평가 방법:"} ${x.assessment_methods}`:"",...(Array.isArray(x.weekly_topics)?x.weekly_topics.map((v:any,i:number)=>`${englishUI?"Week "+(v.week||i+1):locale==="my"?"ပတ် "+(v.week||i+1):(v.week||i+1)+"주차"}: ${typeof v==="string"?v:v.topic||""}`):[])].filter(Boolean);const text=lines.join("\n");try{if(navigator.share)await navigator.share({title:`${courseName(x.course_id)} ${englishUI?"Syllabus":locale==="my"?"သင်ကြားရေးအစီအစဉ်":"강의계획서"}`,text});else{await navigator.clipboard.writeText(text);setNotice((englishUI?"Syllabus content copied. Paste it into a messaging app or email to share.":"강의계획서 내용을 복사했습니다. 메신저나 이메일에 붙여넣어 공유하세요."));}}catch(e:any){if(e?.name!=="AbortError")setError((englishUI?"Unable to open the share dialog. Print to PDF and share the file instead.":"공유 창을 열지 못했습니다. PDF 출력 후 파일로 공유할 수 있습니다."));}};
